+import static org.junit.jupiter.api.Assertions.*;
+import static org.mockito.ArgumentMatchers.anyInt;
+import static org.mockito.Mockito.doThrow;
+
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+    @Autowired
+    private DSLContext dsl;
+
+    @MockitoSpyBean
+    private VetRepository repository;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = {"BR-002", "BR-003"})
+    void navigationShowsNamesAndAlphabeticalSpecialtiesAnonymously() {
+        UI.getCurrent().navigate("");
+        SideNavItem link = assertDoesNotThrow(() -> find(SideNavItem.class)
+                .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(), "Veterinarians link");
+        UI.getCurrent().navigate(link.getPath());
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+        var tester = test(grid());
+        assertEquals(6, tester.size());
+        assertEquals(List.of("First Name", "Last Name", "Specialties"),
+                List.of(tester.getHeaderCell(0), tester.getHeaderCell(1), tester.getHeaderCell(2)));
+        assertEquals("James", tester.getCellText(0, 0));
+        assertEquals("Carter", tester.getCellText(0, 1));
+        assertEquals("none", tester.getCellText(0, 2));
+        assertEquals("Linda", tester.getCellText(1, 0));
+        assertEquals("dentistry, surgery", tester.getCellText(1, 2));
+        assertEquals("Helen", tester.getCellText(3, 0));
+        assertEquals("radiology", tester.getCellText(3, 2));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyDirectoryRendersEmptyGrid() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+        navigate(VetsView.class);
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void dataProviderLoadsBoundedPagesWithoutGapsOrDuplicates() {
+        for (int i = 0; i < 120; i++) {
+            dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME)
+                    .values("Vet", "Test" + String.format("%03d", i)).execute();
+        }
+        navigate(VetsView.class);
+        var provider = grid().getDataProvider();
+        assertFalse(provider.isInMemory());
+        assertEquals(126, provider.size(new Query<>()));
+        var first = provider.fetch(new Query<>(0, 50, List.of(), null, null)).toList();
+        var second = provider.fetch(new Query<>(50, 50, List.of(), null, null)).toList();
+        var last = provider.fetch(new Query<>(100, 50, List.of(), null, null)).toList();
+        assertEquals(50, first.size());
+        assertEquals(50, second.size());
+        assertEquals(26, last.size());
+        var combined = java.util.stream.Stream.of(first, second, last).flatMap(List::stream).toList();
+        assertEquals(repository.findPage(0, 126).toList(), combined);
+        assertEquals(126, combined.stream().map(Vet::id).distinct().count());
+        assertTrue(provider.fetch(new Query<>(126, 50, List.of(), null, null)).findAny().isEmpty());
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void countFailureShowsApplicationErrorWithoutGrid() {
+        doThrow(new DataAccessResourceFailureException("Directory unavailable")).when(repository).count();
+        UI.getCurrent().navigate("vets");
+        if (!find(Grid.class).all().isEmpty()) {
+            grid().getDataProvider().size(new Query<>());
+        }
+        assertErrorWithoutGrid();
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void laterPageFailureReplacesLoadedDirectoryWithApplicationError() {
+        navigate(VetsView.class);
+        Grid<Vet> grid = grid();
+        assertEquals(6, test(grid).size());
+        doThrow(new DataAccessResourceFailureException("Directory unavailable"))
+                .when(repository).findPage(anyInt(), anyInt());
+        assertTrue(grid.getDataProvider().fetch(new Query<>(2, 2, List.of(), null, null)).toList().isEmpty());
+        assertErrorWithoutGrid();
+    }
+
+    private void assertErrorWithoutGrid() {
+        assertDoesNotThrow(() -> find(H2.class).withText("Something happened...").single(),
+                "Application error view must replace the directory");
+        assertTrue(find(Grid.class).all().isEmpty());
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Vet> grid() {
+        return assertDoesNotThrow(() -> find(Grid.class).single(), "Veterinarians grid must be visible");
+    }
+}
